(()=>{let filter='all';const group=status=>status==='completed'?'completed':['cancelled','declined'].includes(status)?'cancelled':'progress',label={all:'All tickets',progress:'In progress',completed:'Completed',cancelled:'Cancelled'};function list(){const bookings=data.bookings||[],shown=filter==='all'?bookings:bookings.filter(x=>group(x.status)===filter),counts={all:bookings.length,progress:bookings.filter(x=>group(x.status)==='progress').length,completed:bookings.filter(x=>group(x.status)==='completed').length,cancelled:bookings.filter(x=>group(x.status)==='cancelled').length};app.innerHTML=`<button class="back" id="tickets-back">← Home</button><div class="intro"><div><div class="eyebrow">MY TICKETS</div><h1>Service requests</h1><p>Track every request in one place.</p></div><span class="pill">${counts.all} total</span></div><section class="card tickets-card"><div class="ticket-filters">${Object.entries(label).map(([id,name])=>`<button type="button" class="${filter===id?'active':''}" data-ticket-filter="${id}">${name}<b>${counts[id]}</b></button>`).join('')}</div><div class="ticket-list">${shown.length?shown.map(ticket=>`<button type="button" class="ticket-row" data-ticket-open="${ticket.id}"><span><strong>${esc(svc(ticket.service).en)}</strong><small>${esc(ticket.village)} · ${esc(ticket.id)}</small></span><span class="ticket-status ${group(ticket.status)}">${esc(status(ticket))}</span></button>`).join(''):`<p class="muted">No ${label[filter].toLocaleLowerCase()} yet.</p>`}</div></section>`;document.querySelector('#tickets-back').onclick=()=>{view='home';render();};app.querySelectorAll('[data-ticket-filter]').forEach(button=>button.onclick=()=>{filter=button.dataset.ticketFilter;list();});app.querySelectorAll('[data-ticket-open]').forEach(button=>button.onclick=()=>{selected=button.dataset.ticketOpen;view='booking';render();});}
 function home(){const card=[...document.querySelectorAll('.card')].find(x=>x.querySelector('h3')?.textContent.includes('Your service requests'));if(!card)return;const bookings=data.bookings||[],active=bookings.filter(x=>group(x.status)==='progress').length;card.classList.add('tickets-card');card.innerHTML=`<div class="eyebrow">MY TICKETS</div><h3>Keep track of your service requests</h3><p class="muted">${bookings.length?`${active} in progress · ${bookings.filter(x=>group(x.status)==='completed').length} completed · ${bookings.filter(x=>group(x.status)==='cancelled').length} cancelled`:'Your requests will appear here once you book a service.'}</p><button type="button" class="secondary" id="open-tickets">Open My Tickets →</button>`;document.querySelector('#open-tickets').onclick=()=>{view='tickets';render();};}
 const baseRender=render;render=function(){baseRender();if(!localToken||!localUser||role!=='customer'||!data)return;const nav=document.querySelector('.account-nav');if(nav&&!document.querySelector('#tickets-nav')){nav.insertAdjacentHTML('beforeend','<button class="quiet" id="tickets-nav">My Tickets</button>');document.querySelector('#tickets-nav').onclick=()=>{view='tickets';render();};}if(view==='tickets')list();else if(view==='home')home();};})();
